<script setup lang="ts">const route=useRoute(); const platform=usePlatformApi(); const {role,setRole}=useRole(); const id=String(route.params.id); const {data:task,pending,error,refresh:reload}=await useAsyncData(`catalog-task-${id}`,()=>platform.getTask(id)); const refresh=()=>reload(); const sections=computed(()=>task.value?[['Контекст',task.value.card.context],['Потребность',task.value.card.need],['Пользователи',task.value.card.users],['Данные и материалы',task.value.card.data],['Ограничения',task.value.card.constraints],['Ожидаемый результат',task.value.card.expectedResult],['Критерии успеха',task.value.card.successCriteria],['Контакт',task.value.card.contact],['Формат взаимодействия',task.value.card.interactionFormat]]:[]);</script>
<template><div class="page"><NuxtLink to="/catalog" class="back-link">В каталог задач</NuxtLink><p v-if="pending">Загружаем задачу…</p><p v-else-if="error" class="error-text">Не удалось загрузить задачу. <button @click="refresh">Повторить</button></p><template v-else-if="task && task.status==='published'"><div class="detail-heading"><span class="badge badge-success">{{ task.card.topic || 'Задача' }}</span><h1>{{ task.card.title }}</h1></div><div class="detail-layout"><div class="detail-main"><article class="panel task-full-card"><section v-for="section in sections" :key="section[0]" class="detail-section"><h2>{{ section[0] }}</h2><p>{{ section[1] || 'Не указано' }}</p></section></article><section class="panel proposal-form-panel"><ProposalForm v-if="role==='team'" :task-id="task.id" /><div v-else class="role-invite"><h2>Есть идея решения?</h2><button class="button button-primary" @click="setRole('team')">Я представляю команду</button></div></section></div><aside class="detail-sidebar"><div class="panel score-panel"><ReadinessScore :score="task.score" /></div></aside></div></template><EmptyState v-else title="Задача не найдена" description="Она не опубликована или была удалена." /></div></template>
